def find_cmd(cmds, name):
  """يلقى الكوماند باسمه أو بأحد أسمائه البديلة. يرجع (الاسم الأصلي، الكوماند) أو (name, None)."""
  if name in cmds:
    return name, cmds[name]
  for k, c in cmds.items():
    if name in (c.get("aliases") or ()):
      return k, c
  return name, None


